  `nopol` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jenis_pekerjaan` enum('p2tl','sr_app','yandal','har') COLLATE utf8mb4_unicode_ci NOT NULL,
  `regu_id` int NOT NULL,
  `nama_pelaksana_1` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `jabatan_petugas` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nama_pelaksana_2` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
