  `catatan_umum` text COLLATE utf8mb4_unicode_ci,
  `foto_kegiatan` mediumblob,
  `foto_kegiatan_mime` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('draft','submitted','approved','rejected') COLLATE utf8mb4_unicode_ci DEFAULT 'draft',
  `ttd_petugas` longtext COLLATE utf8mb4_unicode_ci,
  `petugas_id` int NOT NULL,
