  `ttd_manager` longtext COLLATE utf8mb4_unicode_ci,
  `tanggal_manager` datetime DEFAULT NULL,
  `catatan_manajemen` text COLLATE utf8mb4_unicode_ci,
  `tanggal_approval` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `regu_id` (`regu_id`),
  KEY `petugas_id` (`petugas_id`),
