  `tipe` enum('info','sukses','peringatan','perbaikan') COLLATE utf8mb4_unicode_ci DEFAULT 'info',
  `url_aksi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Link terkait',
