INSERT INTO `notifikasi` VALUES (1,1,'✅ Temuan Diperbaiki: Tang Ampere 3 Phasa','Alat <strong>Tang Ampere 3 Phasa</strong> (RUSAK) yang Anda laporkan pada laporan Regu 2 P2TL Citacontrac (22/09/2026) telah ditandai <strong>selesai diperbaiki</strong> oleh <strong>Yusuf Irfan</strong>.','perbaikan','/sigap/riwayat/detail.php?id=1',1,'2026-09-22 13:11:25'),(2,1,'✅ Temuan Diperbaiki: Tang Ampere 3 Phasa','Alat <strong>Tang Ampere 3 Phasa</strong> (RUSAK) yang Anda laporkan pada laporan Regu 2 P2TL Citacontrac (22/09/2026) telah ditandai <strong>selesai diperbaiki</strong> oleh <strong>Yusuf Irfan</strong>.','perbaikan','/sigap/riwayat/detail.php?id=2',1,'2026-09-22 13:11:34'),(3,2,'✅ Temuan Diperbaiki: Tang Potong','Alat <strong>Tang Potong</strong> (RUSAK) yang Anda laporkan pada laporan Regu 2 P2TL Citacontrac (22/09/2026) telah ditandai <strong>selesai diperbaiki</strong> oleh <strong>Yusuf Irfan</strong>.','perbaikan','/sigap/riwayat/detail.php?id=4',0,'2026-09-22 13:14:18'),(8,2,'Berita Acara Disahkan: GA/P2TL/202609/8205','Laporan gelar alat Anda telah disahkan dan ditandatangani oleh Bindraerda Hanindiawan (TL K3L dan KAM ULP Balong).','sukses','riwayat/detail.php?id=4',0,'2026-09-22 23:40:02'),(9,2,'✅ Temuan Diperbaiki: Kunci Ringpas','Alat <strong>Kunci Ringpas</strong> (RUSAK) yang Anda laporkan pada laporan Regu 2 P2TL Citacontrac (22/09/2026) telah ditandai <strong>selesai diperbaiki</strong> oleh <strong>Yusuf Irfan</strong>.','perbaikan','/sigap/riwayat/detail.php?id=4',0,'2026-09-22 23:50:30'),(10,2,'✅ Temuan Diperbaiki: Obeng Minus (-)','Alat <strong>Obeng Minus (-)</strong> (RUSAK) yang Anda laporkan pada laporan Regu 2 P2TL Citacontrac (22/09/2026) telah ditandai <strong>selesai diperbaiki</strong> oleh <strong>Yusuf Irfan</strong>.','perbaikan','/sigap/riwayat/detail.php?id=4',0,'2026-09-22 23:50:48'),(15,58,'Berita Acara Disahkan: GA/SR_APP/202609/7417','Laporan gelar alat Anda telah disahkan dan ditandatangani oleh Bindraerda Hanindiawan (TL K3L da